import * as React from "react";
import Layout from "../components/layout";
import { graphql, HeadFC, Link, PageProps } from "gatsby";
import data from "../data/data.json";
import { Company } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ImageModal, { type ImageItem } from "../components/ImageModal";
import Carousel from "../components/Carousel";
import SEO from "../components/seo";

const companyData: Company = data as unknown as Company;

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const archiveBase = "/";
  const imageExtensions = ["jpg", "jpeg", "png", "webp"];
  const [modalImages, setModalImages] = React.useState<ImageItem[]>([]);
  const [pendingOpen, setPendingOpen] = React.useState(false);
  const openModalRef = React.useRef<((startIndex?: number) => void) | null>(
    null,
  );

  const openSingleImage = (item: ImageItem) => {
    setModalImages([item]);
    setPendingOpen(true);
  };

  const handleRichTextClick = (event: React.MouseEvent<HTMLElement>) => {
    const target = event.target as HTMLElement;
    const anchor = target.closest("a") as HTMLAnchorElement | null;
    if (!anchor) return;

    const href = anchor.getAttribute("href");
    if (!href || !href.startsWith(archiveBase)) return;

    const normalized = href.split("?")[0].toLowerCase();
    const isImage = imageExtensions.some((ext) =>
      normalized.endsWith(`.${ext}`),
    );
    if (!isImage) return;

    event.preventDefault();
    const label = (anchor.textContent || "").trim();
    openSingleImage({
      src: href,
      alt: label || "Image",
      caption: label || undefined,
    });
  };

  React.useEffect(() => {
    if (!pendingOpen || modalImages.length === 0) return;
    if (!openModalRef.current) return;
    openModalRef.current(0);
    setPendingOpen(false);
  }, [pendingOpen, modalImages]);

  return (
    <Layout data={companyData}>
      <section>
        <ImageModal
          images={modalImages}
          trigger={(open) => {
            openModalRef.current = open;
            return null;
          }}
        />

        <Carousel className="mb-4 sm:mb-8" />
        <section className="text-terracota bg-beige px-6 sm:px-12 py-6 mb-6 shadow-lg">
          <article
            className={styles.content}
            onClick={handleRichTextClick}
            dangerouslySetInnerHTML={{ __html: t("home.content") || "" }}
          />
        </section>

        <section className="text-warm_ivory bg-dark_gray px-12 py-6 mb-6 shadow-lg">
          <section className="flex flex-col sm:flex-row w-full sm:w-1/2 mx-auto justify-between gap-4">
            <Link to="/gallery">
              <h3 className="h2_desk text-center m-6 whitespace-normal sm:whitespace-nowrap">
                {t("menu.gallery")}
              </h3>
              <picture>
                <source
                  srcSet="/photo_gallery/thumb_photo.webp"
                  type="image/webp"
                />
                <img
                  src="/photo_gallery/thumb_photo.jpg"
                  width={700}
                  height={420}
                  className="mx-auto w-full max-w-[700px] h-auto"
                  alt="Photo Gallery Thumb"
                  loading="lazy"
                  decoding="async"
                />
              </picture>
            </Link>
            <Link to="/historic">
              <h3 className="h2_desk text-center m-6 whitespace-normal sm:whitespace-nowrap">
                {t("menu.historic")}
              </h3>
              <picture>
                <source
                  srcSet="/photo_gallery/thumb_historic.webp"
                  type="image/webp"
                />
                <img
                  src="/photo_gallery/thumb_historic.jpg"
                  width={700}
                  height={420}
                  className="mx-auto w-full max-w-[700px] h-auto"
                  alt="Historic Documents Thumb"
                  loading="lazy"
                  decoding="async"
                />
              </picture>
            </Link>
          </section>
        </section>
      </section>
    </Layout>
  );
};

export default IndexPage;

export const Head: HeadFC<any> = ({ data, pageContext }) => (
  <SEO
    data={companyData}
    localesData={data?.locales?.edges?.[0]?.node?.data}
    language={(pageContext as any)?.i18n?.language}
    languages={(pageContext as any)?.i18n?.languages}
    defaultLanguage={(pageContext as any)?.i18n?.defaultLanguage}
    originalPath={(pageContext as any)?.i18n?.originalPath}
    titleKey="home.metaTitle"
    descriptionKey="home.metaDescription"
    authorKey="home.metaAuthor"
    pathname="/"
    schemaType="ProfessionalService"
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  title: "h2_mobile sm:h2_desk text-center mb-6",
  content: "body_mobile sm:body_desk mb-6 text-center",
  author: "h3_mobile sm:h3_desk flex justify-end",
};
